params.command:
$ErrorActionPreference='Continue'; $oc='C:\Users\Xxkan\local-ai-tools\opencode\package\bin\opencode.exe'; $cfg='C:\Users\Xxkan\HeavenBridge\opencode-fallback.json'; @'; {
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "ollama": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "Ollama (local)",
      "options": {
        "baseURL": "http://127.0.0.1:11434/v1"
      },
      "models": {
        "qwen2.5-coder:7b": {
          "name": "Qwen 2.5 Coder 7B local"
        }
      }
    }
  },
  "model": "ollama/qwen2.5-coder:7b"
}; '@ | Set-Content -LiteralPath $cfg -Encoding UTF8; $env:OPENCODE_CONFIG=$cfg; Write-Output '=== VERSION ==='; & $oc --version; Write-Output '=== MODELS ==='; & $oc models 2>&1 | Select-Object -First 80; Write-Output '=== SMOKE ==='; & $oc run --standalone --auto --model 'ollama/qwen2.5-coder:7b' --format json 'Reply with exactly LOCAL_FALLBACK_OK and do not use tools.' 2>&1 | Select-Object -Last 80; Write-Output ('EXIT=' + $LASTEXITCODE)
